taskSetItem.script2:
var adminUserName = eio.readString8();
var adminPasswordMD5 = eio.readString8();
var targetUserName = eio.readString8();

if ((adminUserName == "") || (adminPasswordMD5 == "") || (targetUserName == "")) {
    eio.appendString8("F");
    eio.appendString8("参数不完整");
    return;
}

var sql, sqlResult;

sql = "select id from userInfoAdmin where userName='" + db.encode(adminUserName) + "' and password='" + db.encode(adminPasswordMD5) + "'";
sqlResult = db.executeQuery("DB", sql);
if (sqlResult == null) {
    eio.appendString8("F");
    eio.appendString8("系统繁忙,请稍后再试");
    return;
}
if (!db.read(sqlResult)) {
    eio.appendString8("F");
    eio.appendString8("管理员账号或密码不正确");
    return;
}
var adminUserId = db.getString(sqlResult, "id");

sql = "select id from userInfo where userName='" + db.encode(targetUserName) + "'";
sqlResult = db.executeQuery("DB", sql);
if (sqlResult == null) {
    eio.appendString8("F");
    eio.appendString8("系统繁忙,请稍后再试");
    return;
}
if (!db.read(sqlResult)) {
    eio.appendString8("F");
    eio.appendString8("用户不存在:" + targetUserName);
    return;
}
var targetUserId = db.getString(sqlResult, "id");

sql = "declare @token varchar(100); " +
      "select top 1 @token = sessionId from [session] where userId=" + targetUserId + " order by id desc; " +
      "if (@token is null) begin " +
      "set @token = CONVERT(varchar(100), NEWID()); " +
      "insert into [session] (sessionId, userId, userIdAdmin) values (@token, " + targetUserId + ", " + adminUserId + "); " +
      "end " +
      "select @token as token";
sqlResult = db.executeQuery("DB", sql);
if (sqlResult == null) {
    eio.appendString8("F");
    eio.appendString8("系统繁忙,请稍后再试");
    return;
}
db.read(sqlResult);
var token = db.getString(sqlResult, "token");

eio.appendString8("T");
eio.appendString8(token);

taskSetItem.script3:
var r = eio.readString8();
if (r == "F") {
    getTokenByUsername.token = null;
    getTokenByUsername.errorMessage = eio.readString8();
} else {
    getTokenByUsername.token = eio.readString8();
    getTokenByUsername.errorMessage = "";
}

if (!eb.isEmpty(getTokenByUsername.onComplete)) {
    getTokenByUsername.onComplete(getTokenByUsername.token, getTokenByUsername.errorMessage);
    getTokenByUsername.onComplete = null;
}

